// =====================================================================
//  LINES - chat corpus for the simulated Trainers (Union Room, Club chat, whispers),
//  plus Trainer Card bios and Club names/descriptions. Pure data, read by a6e_people.js.
//  Entry: "text" (any voice) or { t: "text", v: "voice" | ["voice", ...] }.
//  Slots: {me} {to} {op} {op2} {six} {banner} {tier} {pts} {guild} {boss} {leader} {stage} {ep} {n} {lvl} {dmg}.
//    {op}/{op2} Pokémon · {six} a 5★ or legendary · {banner} this week's Safari Zone area · {tier} a Ranked tier
//    {boss} the Club's Raid Battle Pokémon (Club Raid lines only) · {leader} a Journey boss (Gym Leader, Elite Four, Giovanni, Blue)
//    {stage} a Journey stage ("4-3") · {ep} a Journey chapter title · {n} {lvl} {dmg} numbers.
//  Written plain: the engine adds each Trainer's typing style (case, abbreviations, laughs, emoji, typos).
// =====================================================================
