  "Sun offense": "Fire and Solar moves hit hard in the sun", "Chlorophyll offense": "In the sun the Chlorophyll sweepers outspeed nearly everything",
  "Sand offense": "Sand Rush and Sand Force sweepers hit hard in the storm", "Sand balance": "The storm and entry hazards wear foes down while the sweepers finish them",
