  "Full stall": "Everything is about outlasting: screens, status, team healing and walls", "Semi-stall": "Screens, status and walls, plus a bulky Pokémon that boosts to finish things",
  "Hazard phazing": "Hazards and phazers, with healing to keep the walls going", "Bulky phazing": "Hazards, phazers and the bulkiest Pokémon, which outlast everything they drag in",
  "Physical Setup": "Swords Dance, Shift Gear, Victory Dance, Dragon Dance or Belly Drum behind the redirector", "Special Setup": "Quiver Dance, Geomancy, Nasty Plot or Tail Glow behind the redirector",
