  redirect: { need: "mv", t: "{n} draws the attacks with {mv}" }, fakeout: { need: "mv", t: "{n} opens with {mv}" }, status: { need: "mv", t: "{n} spreads status with {mv}" },
  phazer: { need: "mv", t: "{n} forces switches with {mv}" }, pwall: { need: "mv", t: "{n} is the wall, with {mv} to stay healthy" },
  wall: { need: "mv", t: "{n} walls, with {mv} to stay healthy" }, intimidate: { need: "ab", t: "{n} lowers the foes' Attack with Intimidate when it comes in" },
