// questions about this game's own rules, answered the same by everyone (in their own voice)
const TALK_FAQ = [
  // (today's rules, 2026-10-15: the Battle Tower's wings, each Journey's version and teams, the Light Ball, the evolved opponents)
  { re: /battle tower|tower (wing|floor)s?|\bwing\b.{0,20}(tower|floor)|master trainers?/, a: "The Battle Tower has a wing for each region you've opened. Each wing's floors are that region's famous battles the Journey doesn't use, one a floor from the weakest up: the other versions' teams (FireRed and LeafGreen's Koga, Yellow's Blue with his Eevee...), rematches, the Trainers you meet after the League, Battle Frontier Brains, and Let's Go's Master Trainers six to a floor. Every floor clears once. Every fifth gives a Safari Ball and a Rare Candy, and a wing's top floor a Safari Pass, 600 Gems, 5 Rare Candies and 30,000 Poké Dollars. The usual rules hold in there: a later generation's Pokémon battles as the region's own form, and anything Lv 36 or higher has had its stone or trade evolution." },
  { re: /keep (on )?losing|(lost|lose) (a|my|the) (journey|gym|battle)|(free|second|extra|another) starter|professor.{0,30}(mail|letter|sent)|stuck on (a|the) gym/, a: "The first time you lose a Journey battle in a region, that region's Professor sends you Mail to say sorry, with a free starter: your pick of the two you didn't choose. Lose again and the last one comes too, so two at most per region. Each joins you at that battle's level cap, holding Berry Juice like every starter. There are no easier stages any more: every stage sends its waves as one team." },
  { re: /copycat|mirror move/, a: "Copycat and Mirror Move work like Sketch here, just not for good: each comes as an S1, an S2 and an S3 move, and whoever learns one gets all three. Aim one at an opposing Pokémon and it uses that Pokémon's move in the same slot right away, with its own stats, and the Copycat or Mirror Move stays." },
  { re: /\bcounter\b|mirror coat|metal burst|comeuppance|shell trap/, a: "Counter, Mirror Coat, Metal Burst, Comeuppance and Shell Trap can't be chosen here: they go off by themselves. When an opposing attack of the right kind damages the Pokémon (physical for Counter, special for Mirror Coat, either for Metal Burst, Comeuppance and Shell Trap), it strikes back at that attacker once the attack is over, if the move is ready. That doesn't use its turn; the move just goes on cooldown. Counter and Mirror Coat hit back for twice the damage, Metal Burst and Comeuppance for 1.5 times." },
  { re: /conversion/, a: "Conversion and Conversion 2 can't be chosen here: they go off by themselves. Just before an opposing attack's damage, the Pokémon becomes a type that resists it (Conversion 2: one the attack doesn't touch at all, when there is one), if the move is ready. That doesn't use its turn; the move goes on cooldown, and the type lasts until it leaves the field. Conversion is S2, Conversion 2 is S3. Kecleon's Color Change does what Conversion does, every time, since an Ability has no cooldown." },
  { re: /stored power|power trip/, a: "Stored Power and Power Trip work the same here: 50 power, plus 50 for every raised stage on the user's stat badge, up to 250. That counts what an item or Ability fixes there too, so Wise Glasses alone make Stored Power 100, and one Calm Mind on top makes it 200. They're S3 moves." },
  { re: /punishment|rage fist|payback|\brage\b(?! powder)/, a: "Rage, Rage Fist, Punishment and Payback all work the same here: 50 power, plus 50 for every hit the user has taken this battle, up to 250. Take one hit and it's already 100. They're all S2 moves." },
  { re: /\bfrisk\b|anticipation|forewarn/, a: "Frisk, Anticipation and Forewarn actually do things here. Frisk knocks off a random opposing Pokémon's held item when it comes in, once a battle (Sticky Hold keeps it). Anticipation and Forewarn put up a Protect the first time an attack is aimed at them, once a battle. Hit them with something cheap first." },
  { re: /burning jealousy/, a: "Burning Jealousy burns every Pokémon it hits that has a stat at +2 or higher, whatever gave it the boost: a Swords Dance, Huge Power, a Choice item, Tailwind, Swift Swim in rain. Check the stat badge. Sheer Force, Shield Dust and a Covert Cloak stop the burn." },
  { re: /triple kick/, a: "Triple Kick strikes three times at 20, 40 and 60 power, just like Triple Axel. Each strike can miss, unless it holds Loaded Dice." },
  { re: /\bpresent\b/, a: "Present is a gift of 40, 80 or 120 power, or it heals the target a quarter of its HP, and it hits with whichever is higher, the user's Attack or Sp. Atk. With Loaded Dice it's always the 120-power gift, and it never misses." },
  { re: /wing attack|60.power|\bs1\b.*(60|bite|aerial ace)/, a: "Every 60-power attack is an S1 move here, no cooldown: Wing Attack, Bite, Aerial Ace, Water Pulse, Shock Wave... The exceptions stay S2: Round, which doubles with each use like Echoed Voice, and the ones that double in their moment: Revenge and Avalanche when the user's been hit that turn, Assurance when the target has, Barb Barrage on a poisoned target, Infernal Parade on one with a status." },
  { re: /battle tower|tower (floor|wing)|(kanto|johto|hoenn|sinnoh|unova|kalos|alola|galar|paldea)('?s)? wing/, a: "Each Battle Tower wing only takes its own region's Pokémon, and every floor caps your team 2 levels under its strongest opponent. Johto's wing, Johto's Pokémon. Out-leveling it won't help, building the right team will." },
  { re: /cotton down/, a: "Cotton Down here only slows the other side: when an attack hits the Pokémon, each opposing Pokémon on the field drops a Speed stage. Its own partners keep their Speed." },
  { re: /analytic/, a: "Analytic here goes by the Pokémon's own Speed: once it's down a stage or more, its moves are 50% stronger, and 50% more for each stage further down, so ×1.5 at -1, ×2 at -2, up to ×4 at -6. Paralysis and an Iron Ball count, since they're Speed stages here." },
  { re: /light ?ball/, a: "Here the Light Ball works for the whole Pikachu line: Pichu, Pikachu, Raichu and Alolan Raichu all get Attack and Sp. Atk +2 holding it (in the main games it's Pikachu only). Red's Raichu at the top of Mt. Silver holds one." },
  { re: /which (version|game)|what (version|game)|fire ?red|leaf ?green|\byellow\b|\bcrystal\b|\bemerald\b|\bplatinum\b|let'?s go|strongest (team|version)|black 2|white 2/, a: "Each region's Journey tells its fullest game's story: Kanto's is FireRed and LeafGreen's (with both trips to the Sevii Islands), Johto's Crystal's (with the trip to Kanto before Red), Hoenn's Emerald's, Sinnoh's Platinum's. Every battle uses the toughest team any version gave that Trainer, though: in Kanto, Lt. Surge, Erika and Blaine bring Let's Go's teams, Koga, Sabrina and Giovanni's Gym Yellow's, the Elite Four Red and Blue's. The other versions' teams are in the Battle Tower. Unova's, when it comes, has two parts, Black and White, then Black 2 and White 2, each with its own level caps, and you need both before the next region." },
  { re: /(already|why).{0,40}evolved|lv\.? ?36|level 36|evolved (opponents?|pok[eé]mon)/, a: "Every Pokémon you battle in the Journey, Explore or the Battle Tower has evolved once it's at or past its evolution level, and from Lv 36 its stone, trade or friendship evolution too, so Sabrina's Lv 50 Abra and Kadabra are Alakazam. Each region keeps to its own Pokémon first, though: in Kanto a Golbat stays a Golbat, because Crobat is from Johto, and in Johto a Murkrow stays a Murkrow." },
  { re: /trick ?room/, a: "Trick Room puts the slowest Pokémon first for about 5 rounds. Here it goes up by itself the moment its user comes onto the field, if the move is ready, and that doesn't use the user's turn (it just goes on cooldown, like Pursuit or Upper Hand). You can still use it by hand, and either way, if a Trick Room is already up, it ends it, like in the main games. Our backup Trick Room setters wait on the bench until the room is down; if one has to come in while it's up, because nobody else is left, it leaves the room alone. And our Trick Room teams never run anything that slows the other side down (Icy Wind, Electroweb, Rock Tomb, Scary Face, Thunder Wave, Sticky Web): under the room the slower Pokémon moves first." },
  { re: /sand(storm)?.{0,40}(boost|sp\.? ?def|special defen[cs]e|ground|steel)|(ground|steel).{0,40}sand/, a: "A sandstorm gives Rock, Ground and Steel types Sp. Def +1 here (in the main games it's only Rock types), for as long as it lasts, and none of the three take its damage. Everyone else loses 1/16 of their max HP a turn, unless their Ability or Safety Goggles keep it off. It lasts 5 rounds, 8 with a Smooth Rock." },
  { re: /king'?s shield|spiky shield|baneful bunker|obstruct|silk trap|burning bulwark|protect.{0,20}status/, a: "Protect, Detect, Spiky Shield and Baneful Bunker stop status moves too; King's Shield, Obstruct, Silk Trap and Burning Bulwark only stop attacks. A contact move one of them stops costs the attacker: King's Shield Attack −2 (its Generation 6 effect here), Spiky Shield 1/8 of its HP, Baneful Bunker poison, Obstruct Defense −2, Silk Trap Speed −1, Burning Bulwark a burn. Protective Pads keep all of that off." },
  { re: /psychic (terrain|surge|seed)|expanding force|unburden/, a: "Psychic Terrain (Psychic Surge or the move) lasts 5 rounds, 8 with a Terrain Extender. Pokémon on the ground get ×1.5 on Psychic moves, Expanding Force hits every foe at ×1.5, and priority moves from the other side can't touch a Pokémon on the ground, as in the main games. A Psychic Seed is used up the moment the terrain is up (Sp. Def +1), and with Unburden that's Speed +2 for as long as it holds nothing." },
  { re: /terrain|rising voltage|terrain pulse|steel roller|nature power|camouflage|floral healing|mimicry|surge surfer|hadron engine|seed sower|\bseeds?\b/, a: "Terrains last 5 rounds, 8 with a Terrain Extender, and they work on Pokémon on the ground. Electric: Electric moves ×1.5, no falling asleep (Rest and Yawn fail), Rising Voltage doubles. Grassy: Grass moves ×1.5, a little HP back each turn, Earthquake and Bulldoze halved, Floral Healing heals two thirds. Misty: no status or confusion, Dragon moves halved, and it even cures ones a Pokémon on the ground already has (when it goes up, when one comes in, at its turn: our house rule). Psychic: Psychic moves ×1.5, no priority moves against them, Expanding Force hits every foe. Terrain Pulse takes the terrain's type at double power, Nature Power and Camouflage follow it, a Seed is used up in its terrain, and Steel Roller, Ice Spinner and Defog end it." },
  { re: /support|sweepers?|team (layout|build)|how many (setters|sweepers)/, a: "Every Trainer team here has 1 or 2 support Pokémon, bulky ones with Reflect, Light Screen or Aurora Veil and/or Follow Me, Rage Powder or Spotlight, and they lead so the screens and the redirection are up from the start. Weather, terrain and Trick Room teams run two setters and 3 or 4 sweepers picked for them: Swift Swim and Water types in the rain, Fire types and Chlorophyll in the sun, Slush Rush and Ice types in the snow, Sand Rush and Sand Force in the sand, and so on. The lead setter is the less offensive one; the harder hitter waits on the bench as the backup. A lead setter that also has Aurora Veil, a screen or Follow Me counts as the support, which leaves room for a fourth sweeper (Alolan Ninetales, Indeedee)." },
  { re: /follow ?me|rage ?powder|spotlight|redirect/, a: "Follow Me, Rage Powder and Spotlight go off by themselves the moment their user comes onto the field, if the move is ready and a partner is out there, without using its turn (they just go on cooldown, like Trick Room). Follow Me and Rage Powder draw the other side's single-target moves to the user for as long as it stays on the field; Grass types, Overcoat and Safety Goggles ignore Rage Powder. Spotlight can't light up its own user, so it goes on the partner best able to take the hits, never one that's setting up, and that partner draws the attacks for as long as it stays out. With two up on one side, the newest one draws them. Since it lasts, the best users are just bulky: Brute Bonnet, Togekiss, Amoonguss, Clefable, or Clefairy and Togetic with an Eviolite. Speed doesn't matter for them. And we never switch them out: staying out there is the whole point, so they don't run U-turn, Teleport, an Eject Button or Emergency Exit either (Roar, Whirlwind, Dragon Tail and a Red Card can still drag them out). Their healing moves share Follow Me's slot, so Leftovers and draining attacks keep them going, and Regenerator does nothing for them." },
  { re: /attract\b|infatuat|in love|cute charm/, a: "Infatuation works like confusion here (our house rule), except the hit goes to a partner: each turn there's a 1 in 3 chance the infatuated Pokémon attacks one of its partners instead of moving (itself if nobody's beside it) and loses its turn. It lasts 2 to 4 turns, and ends sooner if the one it's in love with leaves the field. Attract and Cute Charm cause it; the Mental Herb, Oblivious and Aroma Veil stop it." },
  { re: /future ?sight|doom desire/, a: "Future Sight and Doom Desire go off by themselves the moment their user comes onto the field, if the move is ready and none of its attacks is already on the way, without using its turn (the move just goes on cooldown), and you can still use them by hand. Two rounds later the whole other side on the field takes the hit." },
  { re: /stealth rock|spikes|sticky web|hazards?\b|reflect\b(?! ?type)|light screen|aurora veil|screens?\b|safeguard|lucky chant|\bmist\b|gravity|wonder room|magic room|rain dance|sunny day|snowscape|tailwind|by itself|on entry|automatic/, a: "Weather moves, terrain moves, the entry hazards (Stealth Rock, Spikes, Toxic Spikes, Sticky Web), Reflect, Light Screen, Aurora Veil, Safeguard, Mist, Lucky Chant, Gravity, Wonder Room and Magic Room all go up by themselves the moment their user comes onto the field, if the move is ready, without using its turn (they just go on cooldown, like Trick Room). If it's already up, the move stays ready for later; a different weather or terrain gets replaced, even your own team's. Hazards only go up with someone on the other side's bench, Aurora Veil only in snow, and we always lead with our screen users so the screens are up from the start. At the start of a battle everyone's go off in Speed order, Abilities too, so the slower setter's weather is the one that stays. Tailwind isn't one of them: it speeds up the whole team with no catch, so you still have to use it on a turn." },
  { re: /backup setter|second setter|two setters|weather (team|setter)|drought|sand stream|snow warning|drizzle/, a: "Sun, Sand and Snow teams here bring their weather with an Ability (Drought or Koraidon's Orichalcum Pulse, Sand Stream, Snow Warning; Groudon and Koraidon count, one Legendary a team), never Sunny Day, Sandstorm or Snowscape, and the setter goes out first. Every weather, terrain and Trick Room team runs two setters: the lead one, holding the rock or the Terrain Extender, and a harder-hitting backup with an attacking item that waits on the bench. The backup only comes in to replace a Pokémon that fainted, and only once the weather, terrain or room is gone (it ran out, or the other side replaced it); we never switch it in. Pelipper leads and Kyogre waits, Hippowdon leads and Tyranitar waits, Female Indeedee leads and Indeedee waits. On Electric Terrain teams Pincurchin leads and Miraidon or Tapu Koko waits, and our Hawlucha holds an Electric Seed: the moment the terrain is up it's used, and Unburden gives Hawlucha Speed +2. A Trick Room backup never comes in while the room is up, since that would end it. Its Room Service makes the room last 8 rounds." },
  { re: /restricted|box legend|two legend|legendar(y|ies) (on|in) (a|my|your) team|mythicals? (on|in) |ultra beasts?|paradox/, a: "In every Stadium battle, Ranked, Link or Friendly, a team can have one Legendary, one Mythical, one Ultra Beast and one Paradox Pokémon at most, so one of each is fine. Koraidon and Miraidon count only as Legendary. The Journey and Explore have no such limit." },
  { re: /johto|hoenn|sinnoh|unova|kalos|alola|galar|paldea|hisui|other regions?|new regions?|next region/, a: "Every region's Pokémon is in the game (the Pokédex goes up to 1,025), but they come one region at a time. A new game starts in one region (Kanto, Johto, Hoenn, Sinnoh, Unova, Kalos, Alola, Galar or Paldea), and only that region's Pokémon battle in its Journey. Unova's Journey has two parts, Black and White's story and then Black 2 and White 2's two years later, each with its own eight Badges and level caps, and you need both. Alola has no Gyms: its island challenge gives a stamp for each of its twelve trials and grand trials, and the Badge bonus counts them as their share of eight; its Totem Pokémon start every battle with an aura that raises their stats, shown on their badge. There's no Dynamax here, so in Galar a Gym Leader's or rival's Dynamax or Gigantamax ace, and every Max Raid Pokémon, battles with an aura instead: Defense and Sp. Def +1, shown on its badge, and double HP, as in the games. There's no Terastallizing either, so in Paldea a Pokémon its Trainer would Terastallize (every Gym Leader's ace, the Elite Four's, Geeta's, the rivals') battles with a Tera aura: Attack and Sp. Atk +1, shown on its badge. Paldea's Journey weaves Victory Road's eight Gyms, the Path of Legends' five Titans and Starfall Street's five Team Star bases together by level; only the Gym Badges count, and the Titans and Team Star bases give Medals. Once your Journey is done (Kanto's ends with Mewtwo at the bottom of Cerulean Cave, Johto's with Red at the top of Mt. Silver, Hoenn's with Steven in Meteor Falls, Sinnoh's with Dialga and Palkia at Spear Pillar, Unova's with Kyurem in the Giant Chasm after Part 2, Kalos's with Zygarde at the bottom of Terminus Cave, Alola's with Team Rainbow Rocket's Giovanni after Ultra Sun and Ultra Moon's Episode RR, Galar's with Peony at the Max Lair after The Isle of Armor and The Crown Tundra, Paldea's with Pecharunt in Kitakami after The Teal Mask, The Indigo Disk and Mochi Mayhem) you choose the next region on the Journey tab: its Professor gives you one of its starters at Lv 5, and its Pokémon start turning up in the Safari Zone. You unlock one region at a time, and only once you've finished the one you're on, until all nine are done; then the Safari Zone's featured areas and events open too. Prizes, gifts and evolutions from a region you haven't opened wait for it. We Trainers go through the regions at our own pace, so some of us have more open than others." },
  { re: /how many pok[eé]mon|pok[eé]dex.*(how many|total|complete)|all \d[\d,]* pok[eé]mon/, a: "1,025 species, Bulbasaur to Pecharunt, plus the forms that count as their own Pokémon: the Alolan, Galarian, Hisuian (Sinnoh's, like Kleavor and the other Hisui Pokémon) and Paldean forms, Rotom's appliances, the Therians and the like. Battle-only forms (Blade Aegislash, School Wishiwashi) only show up mid-battle." },
  { re: /how (do|does|to) .{0,20}evolve|evolution (item|stone)s?|trade evolution|friendship evolution/, a: "Every evolution here is a level or an item. Trade evolutions use the Linking Cord, or the item they'd be traded holding (Metal Coat, King's Rock...); friendship uses the Soothe Bell; the rest use their stone or item. The Poké Mart sells them as your Journey goes on." },
  { re: /mega evol|megas?\b|z-?moves?|dynamax|gigantamax|terastal|\btera\b/, a: "No Mega Evolution, Z-Moves, Dynamax or Terastallizing here. In Galar a Dynamax ace battles with an aura instead (Defense and Sp. Def +1), and in Paldea a Pokémon its Trainer would Terastallize has a Tera aura (Attack and Sp. Atk +1), both shown on its badge for as long as it stays in. Terapagos still takes its Terastal Form with Tera Shift, and Tera Starstorm is a Normal-type move." },
  { re: /quick claw|quick draw|custap/, a: "Quick Claw: +10% turn meter when it's sent out (it moves in the +1 bracket), and after each of its turns a 20% chance to move again right away. Quick Draw does the same with a 30% chance. A Custap Berry makes its holder take its turn the moment it drops to a quarter of its HP." },
  { re: /item clause|two choice|2 choice|same (held )?item twice/, a: "Item Clause: one Choice Band, one Choice Specs, one Choice Scarf, one Life Orb, one Muscle Band, one Wise Glasses, one Assault Vest, one Booster Energy, one Berserk Gene, one Ring Target, one Quick Claw, one King's Rock, one Razor Fang, one Eject Button and one Eject Pack per team. Choice items don't lock moves here, a flinch costs a whole turn, and the Pokémon an Eject Button or Eject Pack sends in comes in protected, so that keeps things fair." },
  { re: /flinch|king'?s rock|razor fang|stench|inner focus/, a: "A flinch costs the Pokémon its next turn here: its turn comes up and it just flinches and can't move. Inner Focus stops it, Steadfast gets Speed +1 out of it. No S1 move can flinch (Bite, Astonish, Twister and the rest are S2), and King's Rock and Razor Fang are one per team (Item Clause)." },
  { re: /magic coat|snatch/, a: "Magic Coat and Snatch go off by themselves, you can't pick them. Magic Coat bounces a status move aimed at its user back (and any other until its next turn); Snatch steals an opposing boosting or healing move: the snatcher gets the boost or the HP, the other side used its move for nothing. Either one goes on cooldown after." },
  { re: /\bbide\b/, a: "Bide starts by itself when its user comes in and stays up until it goes off: the moment it's been hit by two opposing attacks between its own turns, it hits the last attacker for double what those two did. Then it's done until it comes back in. You can't pick it by hand." },
  { re: /(?<!(sleep|stun|rage|poison|cotton|bright|quick|metal|silver|magic) )\bpowder\b(?! snow)|ion deluge/, a: "Powder and Ion Deluge go up by themselves on entry, and you can still use them by hand. Powder covers every opposing Pokémon on the field until it uses a Fire move: that move fails and explodes, 1/4 max HP to it and each partner beside it. Ion Deluge turns every Normal move Electric for 5 rounds, on both sides." },
  { re: /rare cand/, a: "A Rare Candy gives one level, up to your level cap. Cerulean Cave in Explore drops them, and the Poké Mart sells them." },
  { re: /trainer level|account level|trainer lv/, a: "Trainer Level goes up to 100. It rises with the PP you spend, each level refills your PP, and the Growth Fund pays every 5 levels." },
  { re: /level cap|lv cap|\bcap\b/, a: "The level cap is 2 below the strongest Pokémon of your next big battle: a Gym Leader, your rival, Giovanni or the Elite Four, and after the Champion the post-game's big battles, right up to the Journey's last. It's Lv 100 once the whole Journey's done. In Unova the Striaton Gym sets it from the start: N, Bianca and Cheren before it don't. Exp. a capped Pokémon can't use gets shared with the rest of your team." },
  { re: /slot|game corner fever|smeargle|starter bonus/, a: "The Game Corner's slot machine opens with the Prize Corner: 3 Coins a spin plays five lines. 7-7-7 pays 100 Coins and starts the Starter Bonus, 15 free rounds. It pays back about 98% over time, the odds are on the machine, and Game Corner Fever on Mondays gives 20 free spins." },
  { re: /pursuit/, a: "Pursuit is an S2 move here. When the other side switches a Pokémon out, or uses U-turn, Volt Switch, Flip Turn, Teleport or Baton Pass, it hits that Pokémon first by itself for double power. It doesn't use your turn, but it goes on cooldown." },
  { re: /solar ?(beam|blade)/, a: "Solar Beam and Solar Blade hit the same turn here: ×1.5 in harsh sunlight, half power in rain, sandstorm or hail." },
  { re: /sky attack|razor wind|skull bash|meteor beam|two.?turn|charg(e|ing) turn/, a: "No charging turns here: Sky Attack, Razor Wind, Skull Bash and Meteor Beam hit at once, and Skull Bash and Meteor Beam raise Defense or Sp. Atk by 1 before the hit." },
  { re: /phantom force|out of reach|semi.?invuln|\b(use|uses|using|used) (fly|bounce|dig|dive)\b|\b(fly|bounce|dig|dive) (move|users?|turn)\b/, a: "Fly, Bounce, Dig, Dive and Phantom Force take you out of reach until your next turn, then land by themselves. Only the games' exceptions reach you: Thunder, Hurricane, Gust, Twister, Sky Uppercut and Smack Down a flier, Earthquake, Magnitude and Fissure a digger, Surf and Whirlpool a diver, some for double damage. Phantom Force breaks Protect." },
  { re: /outrage|thrash|petal dance/, a: "Outrage, Thrash, Petal Dance and Raging Fury are plain attacks here, no lock-in, but they leave their user confused after the hit (3 or 4 turns)." },
  { re: /uproar/, a: "Uproar keeps everyone on the field awake for 3 rounds, and Rest fails meanwhile." },
  { re: /rollout|fury cutter|echoed voice|the move round|\bround (move|power)/, a: "Rollout, Fury Cutter, Echoed Voice and Round double every time you use them in a battle, other moves in between or not, up to 16×. Defense Curl doubles Rollout again." },
  { re: /magnitude|psywave|loaded dice/, a: "Magnitude rolls 4 to 10 (10 to 150 power). Loaded Dice makes it a 10, Psywave always does its most, and multi-strike moves always strike the most times at 100% accuracy (double and triple strikes too: once the first lands, they all do)." },
  { re: /secret power/, a: "Secret Power's 30% extra effect comes from the field: Electric Terrain paralyzes, Grassy puts to sleep, Misty lowers Sp. Atk, Psychic lowers Speed; sun burns, rain lowers Attack, sandstorm accuracy, hail freezes. With both up you get both, and a plain field paralyzes." },
  { re: /pledge/, a: "Pledges combine: if a teammate used a different Pledge since your last turn, yours becomes a 150-power combined move, with a sea of fire, a swamp or a rainbow for 4 rounds." },
  { re: /heal pulse|pollen puff/, a: "Heal Pulse heals all your partners on the field at once. Pollen Puff still hits its target and also heals every partner by half their max HP." },
  { re: /\bhail\b|\bsnow|icy rock/, a: "Hail and snow are one weather here: everyone but Ice types loses 1/16 HP a turn, and Ice types get Defense +1. Hail and Snowscape both start it, an Icy Rock makes it about 8 rounds, and Ice Body and Snow Cloak go together. Slush Rush keeps the hail off too, our house rule." },
  { re: /\btransform|\bimposter|\bditto\b/, a: "Transform is an S3 move here, and a strong one: the copy is a body of its own, with an HP bar as big as your own max HP. Knock out the copy and the Pokémon just turns back into itself, with the HP and status it had before (it keeps its stat changes). Imposter works the same way." },
  { re: /\bsketch|smeargle/, a: "Smeargle's Sketch comes in three, one for each slot, and it knows all three from the start. Use S1 Sketch on an opposing Pokémon and it copies that Pokémon's S1 move (S2 Sketch its S2 move, S3 Sketch its S3), for good, and uses it right away, the same turn. That's in every battle, even Friendly ones. So a Smeargle can learn any move in the game; the Move Reminder teaches Sketch again if you want to redo a slot. Ours come already sketched." },
  { re: /great ball ticket|ultra ball ticket|mystic ticket|\btickets?\b.*safari|safari.*\btickets?\b/, a: "Each ticket is one throw in its own event area: Great Ball Tickets in the Great Ball Safari (Tuesday and Wednesday, UTC), Ultra Ball Tickets in a Legendary Safari (Friday to Sunday), Mystic Tickets in a Mythical Distribution (a surprise). The Safari Zone shows when each area opens. The event areas (and the weekly ones) open once you've opened every region: until then it's the Whole Park." },
  { re: /synchronoise/, a: "Synchronoise only hits opposing Pokémon that share a type, its status condition, its Ability or its nature with the user (poison and bad poison count as the same). Get yourself burned or poisoned like them and it hits." },
  { re: /hidden ?power/, a: "Hidden Power takes the type of the last attack used on its user, so it changes as the battle goes; until one has been, it's the user's own first type. It's 60 power, physical when the user's Attack is higher than its Sp. Atk, special otherwise." },
  { re: /sent in after|replacement|after a faint|comes in after|protected (when|until)|switch(ing)? (out|in)\b|when (do|should) (i|you) switch/, a: "A Pokémon you send in to take a fainted one's place is protected like Protect until its first turn: moves from the other side fail on it (Feint and the like still break it). Entry hazards, the weather and its status still hurt it. A Pokémon dragged in by Roar or Dragon Tail, or coming in on U-turn or Volt Switch, gets no protection. That's why switching out is rarely worth it here: whoever you switch in comes in with an empty turn meter and no protection, so all three on the other side get to hit it before it moves, and the switch costs your turn. A worn-down Pokémon is usually better off taking its last turn: its replacement comes in protected." },
  { re: /focus ?punch/, a: "Focus Punch never loses its focus here, getting hit doesn't stop it, but it only has 70% accuracy." },
  { re: /\bendure\b|reversal|\bflail\b|endeavor/, a: "Endure hangs on at 1 HP when a hit would knock you out. Then Reversal and Flail hit at 200 power, and Endeavor brings the target down to your HP. A Focus Sash does the same from full HP." },
  { re: /\brest\b|chesto|sleep talk|\bsnore\b/, a: "Rest heals everything, then you sleep through your next turn (sleep is shorter here than in the main games). It fails at full HP, when you're already asleep, or when you can't fall asleep (Insomnia, Electric or Misty Terrain). A Chesto or Lum Berry wakes you at once, Hydration does in rain, Shed Skin might, Early Bird wakes you twice as fast, and a sleeping Pokémon that knows Snore uses it by itself." },
  { re: /belly ?drum/, a: "Belly Drum maxes your Attack for half your HP. A Sitrus Berry gives a quarter back straight away." },
  { re: /\btrick\b|switcheroo/, a: "Choice items don't lock your move here, so Tricking one onto a foe just powers it up. Trick a Flame Orb, Toxic Orb, Iron Ball, Lagging Tail or Sticky Barb instead." },
  { re: /weather ?ball/, a: "Weather Ball takes the weather's type and doubles to 100 power: Fire in harsh sunlight, Water in rain, Rock in a sandstorm, Ice in the snow. It's a special move, so on weather teams our special attackers run it and the physical ones never do." },
  { re: /booster energy|protosynthesis|quark drive/, a: "Protosynthesis turns on in harsh sunlight and Quark Drive in Electric Terrain, or with Booster Energy, which is never used up here. On a sun team or an Electric Terrain team the field already does it, so we give those Paradox Pokémon an attacking item instead and keep the Booster Energy (one a team) for one that needs it." },
  { re: /ring ?target/, a: "Ring Target works for its holder here: its moves hit Pokémon that would be immune, by type or by Ability, for ×1 damage. Ground moves hit Flying types and Levitate, Electric hits Ground types, Lightning Rod and Volt Absorb (their Ability still works: Lightning Rod still draws the attack and still gets its Sp. Atk boost), Normal and Fighting hit Ghosts, and Thunder Wave reaches Ground types. Every Electric Terrain team here has one, so its Electric attacks still hit Ground types. It's best on spread attackers: Earthquake hits every foe, and about half the top teams' Pokémon are Flying or have Levitate, so without it those just take nothing; same for Zapdos's Discharge or Jolteon's Electroweb into Ground types, Lightning Rod and Volt Absorb. A single-target attacker only gains it where its other moves can't cover (Gengar's Sludge Wave already handles Normal types, Machamp's Payback handles Gengar). Regieleki, Xurkitree and Spectrier always run one: nearly everything they hit with is Electric or Ghost. One per team (Item Clause)." },
  { re: /weakness policy/, a: "Weakness Policy gives +2 Attack and Sp. Atk when its holder survives a super-effective hit. Behind Reflect or Light Screen it survives much more easily. Against one, knock it out in one go, or hit it neutrally." },
  { re: /\bhex\b|venoshock/, a: "Hex hits for double against a target with a status condition, Venoshock against a poisoned one. Have a teammate burn, paralyze or poison the target first, or set Toxic Spikes on the other side." },
  { re: /focus energy|scope lens|razor claw/, a: "Focus Energy plus a high critical-hit move or a Scope Lens means every hit is a critical hit." },
  { re: /combo|synerg/, a: "Good combos: Endure then Reversal or Endeavor, Rest with a Chesto Berry or Snore, Belly Drum with a Sitrus Berry, Defense Curl before Rollout, Charge before an Electric move, Focus Energy with a high critical-hit move, screens with a Weakness Policy holder, a teammate's Will-O-Wisp or Toxic Spikes before Hex or Venoshock, and Roar or Whirlwind into your entry hazards." },
  { re: /hyper ?beam|giga ?impact|blast ?burn|frenzy ?plant|hydro ?cannon|rock wrecker|roar of time|steel beam|chloroblast/, a: "No recharging here: Hyper Beam, Giga Impact, Blast Burn, Frenzy Plant, Hydro Cannon, Rock Wrecker and Roar of Time just go on cooldown like any S3 move. Steel Beam, Chloroblast and Mind Blown cost a quarter of your max HP, hit or miss, and every recoil move takes a quarter of the damage it deals. Moves that lower your own stats, like Close Combat or Draco Meteor, don't here." },
  { re: /triple axel/, a: "Triple Axel hits at 20, 40 and 60 power, and each strike can miss." },
  { re: /\bthunder\b(?! ?(bolt|wave|punch|fang|shock|stone|cage))|hurricane|blizzard/, a: "Thunder and Hurricane never miss in rain and drop to 50% accuracy in harsh sunlight. Blizzard never misses in hail." },
  { re: /\bsnore\b/, a: "Snore only works while you're asleep, and a sleeping Pokémon that knows it snores by itself." },
  { re: /minimize|defense curl|\bcharge\b/, a: "Minimize: Stomp, Body Slam, Dragon Rush, Heavy Slam, Heat Crash and Steamroller hit you twice as hard and never miss, and so does Flying Press against any raised evasiveness. Defense Curl doubles Rollout, and Charge doubles your next Electric move." },
  { re: /gluttony/, a: "Gluttony eats its HP Berry the moment it takes any damage." },
  { re: /arena trap|magnet pull|run away|trapped|can'?t switch/, a: "Arena Trap stops grounded opposing Pokémon switching out and slows their turn meters; Magnet Pull does that to Steel types. Run Away is never trapped by anything, and Shed Shell always gets out." },
  { re: /intimidate/, a: "Intimidate lowers Attack by 1 on the way in. Inner Focus, Own Tempo, Oblivious and Scrappy ignore it, and Rattled gets faster from it." },
  { re: /sturdy/, a: "Sturdy holds on at 1 HP from full HP, every time it's hit at full HP. There are no one-hit KO moves here to stop: Fissure, Horn Drill, Guillotine and Sheer Cold take half the target's HP, like Super Fang." },
  { re: /fissure|horn drill|guillotine|sheer cold|one-?hit ko|ohko|super fang|ruination|nature'?s madness/, a: "Fissure, Horn Drill, Guillotine and Sheer Cold work like Super Fang, Ruination and Nature's Madness here: they take half the target's current HP, at 90% accuracy. Types still decide who they can hit (Fissure can't touch Flying-types or Levitate), and Sheer Cold hits Ice-types too." },
  { re: /dry skin/, a: "Dry Skin soaks up Water moves, heals 1/8 a turn in rain, loses 1/8 in harsh sunlight, and takes 25% more from Fire." },
  { re: /assault vest/, a: "Assault Vest gives Sp. Def +1, a stat stage that stays as long as it's held, and here its holder can still use status moves. One per team (Item Clause)." },
  { re: /life orb|sheer force/, a: "Life Orb gives Attack and Sp. Atk +1 and costs 1/10 HP per attack, but not on moves Sheer Force powers up, and never with Magic Guard. One per team (Item Clause)." },
  { re: /stat stage|choice (band|specs|scarf)|eviolite|muscle band|wise glasses|booster energy|huge power|stat (changes?|boosts?)|burn(ed|s)? .*attack|paralys(is|ed) .*speed/, a: "Every stat change here is a stat stage, and it shows on the stat badge: Choice Band is Attack +1, Huge Power Attack +2, Eviolite Defense and Sp. Def +1, a burn Attack −2, paralysis Speed −2, Tailwind Speed +2. The ones from items, Abilities, the weather and a status stay as long as their source does (Haze, Clear Smog and White Herb don't touch them), they add up with the ones moves make, ±6 at most together, and critical hits and Unaware ignore only the ones moves made. Booster Energy is never used up, Assault Vest allows status moves, Gorilla Tactics doesn't lock a move, and Unburden works whenever its holder has no item." },
  { re: /figy|wiki berry|mago|aguav|iapapa/, a: "Figy, Wiki, Mago, Aguav and Iapapa Berries heal 1/3 of your HP at 1/4 and never confuse here, whatever the Nature." },
  { re: /portrait|landscape|\bshape\b|gameboy mode|switch mode|switch shape/, a: "Settings, Game Boy, Shape: Gameboy is the upright one, Switch the long and low one, and Hybrid follows your screen." },
  { re: /fake ?out/, a: "Fake Out works on any turn here, not just your first one, so it's an S2 move with a cooldown. It's still a priority move (+30% turn meter when its user comes in) and always makes the target flinch, so it loses its next turn." },
  { re: /priority|quick attack|extreme ?speed|sucker ?punch|quick ?claw|prankster/, a: "Priority works on the turn meter here: every priority move a Pokémon knows gives it 10% turn meter for each point of its priority the moment it's sent out. Quick Attack and Mach Punch +10%, Extreme Speed +20%, Fake Out +30%, Protect +40%, Helping Hand +50%. Prankster, Gale Wings, Quick Draw and the Quick Claw count as +1, Triage as +3. They add up." },
  { re: /\bs3\b|\bs2\b|cooldown/, a: "S1 moves have no cooldown; S2 and S3 moves do, and S3 moves are ready from the first turn. ★ Mastery cuts a cooldown by one." },
  { re: /\bspeed\b|turn meter|go first|move first/, a: "Speed fills the turn meter faster, so a fast Pokémon acts more often, not just first. Agility-style boosts give about a quarter to half more turns." },
  { re: /\bmints?\b|\bnatures?\b/, a: "Mints change a Pokémon's nature. The Poké Mart sells them for 10,000 each, and you use them from its Summary." },
  { re: /ability (capsule|patch)|change (its |an |my )?abilit|hidden abilit/, a: "The Ability Capsule (150 BP) switches between regular Abilities and the Ability Patch (400 BP) gives the Hidden one. Both are at the BP Exchange." },
  { re: /\btms?\b|technical machine|\bhms?\b|\btrs?\b/, a: "The Poké Mart's TM counter sells six TMs at a time and changes every 15 minutes. Each TM teaches its move once." },
  { re: /move reminder|relearn|forgot (a |its )?move/, a: "The Move Reminder on the Moves tab teaches a level-up move it skipped, for Poké Dollars." },
  { re: /move tutor|heart scale|egg moves?|tutor moves?/, a: "The Move Tutor on the Moves tab teaches egg moves and tutor moves from every game, one Heart Scale each. The Poké Mart sells Heart Scales for 5,000, the BP Exchange for 40 BP, and Explore turns one up now and then." },
  { re: /recharge|top.?up|\bvip\b/, a: "Recharge is free once an hour in the Event Center: a random Gem pack, and each pack's first time is doubled. Recharged Gems raise your VIP: more PP, Tickets and a daily gift." },
  { re: /server|merge/, a: "There's one server, and everyone's on it. This world started with your new game: you and all of us began the same day, from our first Pokémon. Some of us play more, or faster, so we're spread across the regions now. The Server tab in the Event Center has its goals, firsts and rankings." },
  { re: /lotter|auction/, a: "The Champion Lottery and the Server Auction run every day. The Lottery draws at 00:00 UTC, and the top Auction bid then wins; outbid Gems come straight back." },
  { re: /check.?in|pok[eé] ?pass|growth fund|investment/, a: "The Check-In follows the calendar: any day this month can still be claimed. The Poké Pass keeps missed days too. The Growth Fund pays every 5 Trainer Levels up to 100, and the Investment Plan is for your first 7 days." },
  { re: /boutique|outfit|costume|new look|change (my )?look/, a: "The Boutique in Celadon Dept. Store sells new looks for 3,000 Gems each: Ash, Dawn, N, Serena and the rest. Wear them from your Trainer Card." },
  { re: /rookie|login bonus/, a: "New Trainers get Rookie Week: a login bonus for each of your first days and Rookie Missions to finish within your first 7 days." },
  { re: /\bunlock|\blocked\b|\bopens? up\b/, a: "Things open as you go through the Journey: Mail after the rival, the Safari Zone once you finish your first chapter, the Event Center in Mt. Moon, Ranked after Lt. Surge, Link Battles at the Pokémon Tower." },
  { re: /\bgems?\b/, a: "Gems come from the hourly Recharge, Journey stars, Daily Research, Medals, events and Mail. Spend them on Safari throws, offers, passes and extra Explore tries; a Gem Consumption Rush pays extra for spending them." },
  { re: /pok[eé] ?dollars|money|\bcash\b/, a: "Rocket Hideout in Explore pays the most Poké Dollars, and an Amulet Coin doubles what battles pay." },
  { re: /exp\.? candy|\bexp\b|level up fast|grind levels|level (my|them) up/, a: "Cerulean Cave in Explore drops Exp. Candy, and a Lucky Egg gives 50% more Exp." },
  { re: /explore|tries/, a: "Each Explore area has 3 tries a day; more tries cost Gems." },
  { re: /mastery|seeds? of mastery/, a: "Seeds of Mastery raise a move's Mastery: 6% stronger per rank, and ★ cuts its cooldown by one." },
  { re: /\bbp\b|battle points|bp exchange/, a: "Battle Points come from Link Battles. Spend them at the BP Exchange on held items, the Ability Capsule and the Ability Patch." },
  { re: /safari/, a: "Safari Balls are for the Safari Zone. The Whole Park has the Pokémon of every region you've opened; once you've opened all nine, the featured areas (new ones every week) and the event areas open too." },
  { re: /dream eater/, a: "Dream Eater works on anything here, asleep or not." },
  { re: /whirlwind/, a: "Whirlwind is a 60-power S1 attack here that never misses, and it still blows the target away." },
  { re: /friendly|practice battle/, a: "Every Trainer's profile has a Battle button: a friendly against their Registered Team. No points, no record, just practice." },
  { re: /ranked|link battle|draft/, a: "Ranked Battles pit your team against other Trainers' Registered Teams for points. Link Battles are a live draft: seven picks each and a ban." },
  { re: /held items?|what do items do/, a: "Held items work in battle. Berries come from the Poké Mart, battle items from the BP Exchange, and the rest from Explore." },
];
